#include <vector>
#include <cmath>
#define main hecbench_original_main
#include "scan3-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;std::vector<float>input(n),out(n);std::vector<double>expected;double acc=0;for(int i=0;i<n;i++){input[i]=float((i*17)%13+1);expected.push_back(acc);acc+=input[i];}std::vector<double>copy=expected;expected.insert(expected.end(),copy.begin(),copy.end());float *di,*dr;cudaMalloc(&di,n*4);cudaMalloc(&dr,n*4);cudaMemcpy(di,input.data(),n*4,cudaMemcpyHostToDevice);auto launch=[&](int mode){if(mode==1){thrust::device_ptr<float>in(di),out(dr);thrust::exclusive_scan(in,in+n,out,0.f);}else{void*temp=nullptr;size_t bytes=0;cub::DeviceScan::ExclusiveScan(temp,bytes,di,dr,Sum(),0.f,n);cudaMalloc(&temp,bytes);cub::DeviceScan::ExclusiveScan(temp,bytes,di,dr,Sum(),0.f,n);cudaFree(temp);}};launch(1);launch(2);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double total=0;std::vector<double>values;for(int mode=1;mode<=2;mode++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)launch(mode);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(out.data(),dr,n*4,cudaMemcpyDeviceToHost);for(float v:out)values.push_back(v);}emit(trial,total,values,expected,repeat);}cudaFree(di);cudaFree(dr);return 0;}
